import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.BGyYNsHo.js";const m=JSON.parse('{"title":"Surcharge Methods","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/hydraulics/09-surcharge-methods.md","filePath":"explanation/hydraulics/09-surcharge-methods.md"}'),o={name:"explanation/hydraulics/09-surcharge-methods.md"};function i(h,e,l,n,d,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="surcharge-methods" tabindex="-1">Surcharge Methods <a class="header-anchor" href="#surcharge-methods" aria-label="Permalink to &quot;Surcharge Methods&quot;">​</a></h1><h2 id="surcharge-methods-1" tabindex="-1">Surcharge methods <a class="header-anchor" href="#surcharge-methods-1" aria-label="Permalink to &quot;Surcharge methods&quot;">​</a></h2><p>The <code>SURCHARGE_METHOD</code> option selects how pressurized flow in closed conduits is treated. All three methods update the flow area of a surcharged conduit (depth $&gt; y_{\\mathrm{full}}$) by adding a narrow slot of width $w_s$:</p><p>$$A = A_{\\mathrm{full}} + (y - y_{\\mathrm{full}}),w_s,$$</p><p>while the hydraulic radius is clamped to its full value $R_{\\mathrm{full}}$ (the slot contributes storage but not friction).</p><h3 id="extran-default" tabindex="-1">EXTRAN (default) <a class="header-anchor" href="#extran-default" aria-label="Permalink to &quot;EXTRAN (default)&quot;">​</a></h3><p>The classical perturbation method of <a href="./08-node-continuity.html">Node continuity, flooding, and surcharge</a>: $dQ/dH$-based surcharged node updates with a crown cutoff at $y/y_{\\mathrm{full}} = 0.96$ used for the width used in the surface-area computation.</p><h3 id="static-preissmann-slot" tabindex="-1">Static Preissmann slot <a class="header-anchor" href="#static-preissmann-slot" aria-label="Permalink to &quot;Static Preissmann slot&quot;">​</a></h3><p>The conduit carries a fictitious narrow slot above the crown so the free-surface formulation remains valid throughout pressurization. The slot width follows the Sjöberg (1982) formula,</p><p>$$\\frac{w_s}{W_{\\max}} = 0.5423, \\exp!\\left(-\\left(\\frac{y}{y_{\\mathrm{full}}}\\right)^{2.4}\\right),$$</p><p>applied for $0.985257 \\le y/y_{\\mathrm{full}} \\le 1.78$, clamped at $w_s = 0.01,W_{\\max}$ above that, and zero below the cutoff.</p><h3 id="dynamic-preissmann-slot" tabindex="-1">Dynamic Preissmann slot <a class="header-anchor" href="#dynamic-preissmann-slot" aria-label="Permalink to &quot;Dynamic Preissmann slot&quot;">​</a></h3><p>An OpenSWMM extension (Sharior, Hodges &amp; Vasconcelos 2023) in which the slot area evolves in time as an element of transient storage. The slot top width is driven by a target pressure-wave celerity $c_{pT}$ and a time-varying Preissmann number $P$:</p><p>$$T_s = \\frac{g,A_{\\mathrm{full}}}{c_{pT}^{2}},P^{2}, \\qquad P_{0} = \\max!\\left(\\frac{c_{pT}}{\\alpha,c_g},\\ 1\\right), \\qquad c_g = \\sqrt{g,A_{\\mathrm{full}}/W_{\\max}},$$</p><p>with the shock parameter $\\alpha = 3$ (default). The accumulated slot area is path-dependent,</p><p>$$A_s \\leftarrow \\max!\\left(A_s + T_s,\\Delta h_s,\\ 0\\right), \\qquad h_s = \\max(\\bar y - y_{\\mathrm{full}},\\ 0),$$</p><p>and $P$ decays exponentially after pressurization onset and is spatially smoothed across nodes. While a slot is active, the top width is $T_s$ and the surface area contributed to a surcharged end node is $T_s,L/4$. Nodal heads are updated with the ordinary free-surface formula at all times; the surcharge branch is never invoked. The variable time step uses the pressure celerity $c_p = c_{pT}/P$.</p>',17)])])}const p=a(o,[["render",i]]);export{m as __pageData,p as default};
